    /// The canonical Codicon TTF filename.
    public static let fontFilename = "codicon.ttf"

    /// The contract-pinned SHA-256 of the canonical Codicon TTF
    /// (`cc2472e2…6333a8`), transcribed from the T1-R registry-token-icon
    /// closure and the G4-R/G6-R authoritative manifests. The font binary is
    /// NOT bundled in the MonaCode Core (source acquisitions: 0; no binary
    /// exists in the repo and downloading/fabricating is forbidden). When the
    /// AppKit layer acquires the font, its SHA-256 must equal this value.
    public static let expectedFontSHA256 = "cc2472e239e17062e7760af87f8f5997720cc0d94aa014a615c418baaf6333a8"

    /// The canonical Codicon TTF size in bytes (140956), transcribed from the
    /// G4-R authoritative manifest (C10 overlay).
    public static let expectedFontSizeBytes = 140956

    /// `true` — the font binary is intentionally absent from the Core; the
    /// AppKit rendering layer is responsible for acquiring matching bytes.
    public static let fontBinaryBundled: Bool = false

    /// License provenance transcribed verbatim from the G4-R/G6-R
    /// `licensingProfile`.
    public static let provenance = MonaCodiconProvenance(
        artworkAndFontLicense: "CC BY 4.0; retain attribution, license reference and modification notice",
        gitLogoException: "CC BY 3.0 attribution and license are retained when the bundled full font includes the Git Logo glyph",
        generatorAndCodeLicense: "MIT",
        monacoMitNotice: "MIT; Monaco editor and theme data retain the upstream MIT notice and provenance."
    )

    private static let idIndex: [String: Int] = {
        var idx: [String: Int] = [:]
        for (i, g) in glyphs.enumerated() { idx[g.id] = i }
        return idx
    }()

    /// Looks up a glyph entry by icon id.
    public static func glyph(for id: String) -> Glyph? {
        guard let i = idIndex[id] else { return nil }
        return glyphs[i]
    }

    /// All 776 glyph ids in source-ordinal order.
    public static var ids: [String] { glyphs.map { $0.id } }

    /// The number of glyph entries (776).
    public static var count: Int { glyphs.count }
}

